return [
  { json: { id: 1, subject: 'Fatura vencida - R$ 350,00', body: 'Seu boleto está com vencimento urgente. Valor: R$ 350,00. Pague para evitar juros.' } },
  { json: { id: 2, subject: 'Sistema fora do ar', body: 'Estou com problema no login, o sistema apresenta erro 500 desde ontem.' } },
  { json: { id: 3, subject: 'Promoção exclusiva para você!', body: 'Aproveite nosso desconto de 50% em todos os planos. Oferta por tempo limitado!' } }
];

const RULES = [
  { category: 'Financeiro', keywords: ['boleto','pagamento','fatura','cobrança','pix','nfe','nota fiscal','débito','crédito','vencimento','invoice'] },
  { category: 'Suporte', keywords: ['erro','problema','suporte','falha','não funciona','bug','ajuda','help','ticket','incidente'] },
  { category: 'Vendas', keywords: ['promoção','desconto','compre agora','oferta','grátis','clique aqui','ganhe','propaganda','venda','plano','assine'] }
];

const subject = $input.item.json.subject || '';
const body = $input.item.json.body || '';
const text = (subject + ' ' + body).toLowerCase();

let categoria = 'Outros';
for (const rule of RULES) {
  if (rule.keywords.some(kw => text.includes(kw))) {
    categoria = rule.category;
    break;
  }
}

return { json: { id: $input.item.json.id, subject, body, categoria } };
